// Extract topic from webhook OR use auto-rotation
const topic = $json.body?.topic || $json.query?.topic || null;
const videoType = $json.body?.type || 'short';

// Auto-rotate topics by day of week
const topics = [
  'A free AI tool that helps Indian students earn ₹10K/month with zero investment',
  'The ChatGPT trick that 99% users dont know — this changes everything',
  'How to build a ₹50K/month automation side hustle with n8n for free',
  'Top 5 free AI tools every Indian student must have in 2026',
  'A Gemini API hack that replaces ₹5000/month paid tools'
];

const dayOfWeek = new Date().getDay();
const autoTopic = topics[dayOfWeek % topics.length];

return [{ json: { topic: topic || autoTopic, videoType } }];

// Parse Gemini response
const responseText = $json.candidates[0].content.parts[0].text;
let scriptData;

try {
  scriptData = JSON.parse(responseText);
} catch(e) {
  const match = responseText.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  scriptData = JSON.parse(match ? match[1] : responseText.trim());
}

// Add metadata
scriptData.generated_at = new Date().toISOString();
scriptData.topic = $node['Pick Topic'].json.topic;

return [{ json: scriptData }];

