// Combine all data into final package
const script = $node['Parse Script'].json;
const titles = JSON.parse($node['Gemini — Generate Title Variants'].json.candidates[0].content.parts[0].text);
const descData = JSON.parse($node['Gemini — Generate Description'].json.candidates[0].content.parts[0].text);

const finalPackage = {
  title: script.title,
  title_variants: titles.titles || [],
  script: script.script,
  hashtags: script.hashtags || [],
  thumbnail_text: script.thumbnail_text,
  description: descData.description,
  tags: descData.tags || [],
  generated_at: script.generated_at,
  topic: script.topic,
  status: 'ready_for_voice_and_video'
};

return [{ json: finalPackage }];
